// The Handbook book, generated by data/handbook_v4/build_handbook_v4.py (same chapters as the app; do not edit the JSON).
import book from "./handbook.json";
import bookChapters from "./handbook_book.json"; // Book layout, generated by data/handbook_book/build.py; local preview only
import type { Block } from "@/components/handbook-blocks";

export type Chapter = { volume?: string; number?: number; slug: string; part: string; partTitle: string; title: string; summary: string; minutes: number; sources: Record<string, string>; blocks: Block[] };

const bookSlugs = new Set(bookChapters.map((c) => c.slug));
export const chapters = [...bookChapters, ...book.filter((c) => !bookSlugs.has(c.slug))] as unknown as Chapter[]; // checked by the builder (check_book), not by TypeScript
export const chapterBySlug = (slug: string) => chapters.find((c) => c.slug === slug);

export const HANDBOOK_NOTE =
  "General information from published guidelines, not medical advice, and not reviewed by a clinician. See a doctor for pain, illness, pregnancy or before hard training if you have a condition.";
